DROP TABLE IF EXISTS `recipes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recipes` (
  `recipes_id` bigint NOT NULL AUTO_INCREMENT,
  `users_id` bigint NOT NULL,
  `title` varchar(255) NOT NULL,
  `main_image_url` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `cook_time` int NOT NULL,
  `servings` int NOT NULL,
  `scrap_count` int NOT NULL DEFAULT '0',
  `review_count` int NOT NULL DEFAULT '0',
  `average_rating` double NOT NULL DEFAULT '0',
  `recipe_type` enum('USER','CHEF') NOT NULL DEFAULT 'USER',
  `calories` double NOT NULL DEFAULT '0',
  `carbohydrate` double NOT NULL DEFAULT '0',
  `protein` double NOT NULL DEFAULT '0',
  `saturated_fat` double NOT NULL DEFAULT '0',
  `cholesterol` double NOT NULL DEFAULT '0',
  `sodium` double NOT NULL DEFAULT '0',
  `calcium` double NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`recipes_id`),
  KEY `fk_recipe_user` (`users_id`),
  CONSTRAINT `fk_recipe_user` FOREIGN KEY (`users_id`) REFERENCES `users` (`users_id`)
) ENGINE=InnoDB AUTO_INCREMENT=746 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
